"use strict";
class Store {
  constructor(name) {
    this.name = name;
    this.entries = new Map();
  }
  get size() {
    return this.entries.size;
  }
  add(name, value) {
    if (name === "") throw new TypeError("entry names must not be empty");
    const entry = { name, value, owner: this };
    this.entries.set(name, entry);
    return entry;
  }
  get(name) {
    return this.entries.get(name);
  }
  total() {
    let sum = 0;
    for (const e of this.entries.values()) sum += e.value;
    return sum;
  }
  rename(entry, name) {
    this.entries.delete(entry.name);
    entry.name = name;
    this.entries.set(name, entry);
  }
  first() {
    return this.entries.values().next().value ?? null;
  }
}
exports.Store = Store;
